SELECT COUNT(*) AS total_customers
FROM district
WHERE A3 = 'North Bohemia' AND A11 > 8000;

SELECT district_id 
FROM account 
WHERE account_id = (SELECT account_id FROM order WHERE order_id = 33333);

SELECT user_id 
FROM order 
WHERE order_id = 32423;

SELECT element
FROM atom
WHERE molecule_id = 'TR004';

SELECT bond_type 
FROM bond 
WHERE molecule_id BETWEEN 'TR000' AND 'TR050';

SELECT COUNT(*) AS total_carcinogenic_molecules
FROM molecule
WHERE label = '+';

SELECT COUNT(*) 
FROM cards 
WHERE borderColor = 'borderless' AND edhrecRank > 12000;

SELECT artist, COUNT(*) AS card_count
FROM cards
GROUP BY artist;

SELECT OwnerDisplayName
FROM posts
WHERE FavoriteCount = (SELECT MAX(FavoriteCount) FROM posts);

SELECT COUNT(*)
FROM users
WHERE Location LIKE '%New York%';

SELECT OwnerDisplayName
FROM posts
WHERE ViewCount = (SELECT MAX(ViewCount) FROM posts);

SELECT superhero_name 
FROM superhero 
WHERE eye_colour_id = 7 AND hair_colour_id = 9;

SELECT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed BETWEEN 51 AND 59;

SELECT first_name || ' ' || last_name AS full_name, email
FROM member
WHERE position = 'Secretary';

SELECT first_name || ' ' || last_name AS full_name, email
FROM member
WHERE position = 'Secretary';
